pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 10 ether);
        vm.deal(bob, 5 ether);

        vm.prank(alice);
        (bool sentAlice, ) = address(c).call{value: 10 ether}("");
        require(sentAlice, "alice deposit failed");

        vm.prank(bob);
        (bool sentBob, ) = address(c).call{value: 5 ether}("");
        require(sentBob, "bob deposit failed");

        vm.prank(alice);
        c.withdraw();

        assertTrue(c.balances(alice) == 0);
    }
}

