pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "deposit failed");
        uint256 balanceBefore = c.balances(alice);
        vm.prank(alice);
        c.withdraw();
        uint256 balanceAfter = c.balances(alice);
        assertTrue(balanceAfter == 0, "balance should be zero after withdraw");
    }
}

