// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);
        vm.prank(alice);
        (bool sent1, ) = address(c).call{value: 1 ether}("");
        require(sent1);
        vm.prank(bob);
        (bool sent2, ) = address(c).call{value: 1 ether}("");
        require(sent2);
        vm.prank(bob);
        c.withdraw();
        vm.prank(alice);
        uint256 balanceBefore = address(alice).balance;
        c.withdraw();
        uint256 balanceAfter = address(alice).balance;
        assertTrue(balanceAfter - balanceBefore == 1 ether);
    }
}
